  /\ (TCX + 0x10000 <= K_LOW_SHADOW_lo \/ K_HIGH_SHADOW_hi <= TCX) /\ (PAB + 0x800000 <= K_LOW_SHADOW_lo \/ K_HIGH_SHADOW_hi <= PAB)
